 async function remove(kind:"entry"|"batch"|"kbatch"|"kentry",id:string){const collection=kind==="entry"?"entries":kind==="batch"?"batches":kind==="kbatch"?"kombuchaBatches":"kombuchaEntries";const next={...book,[collection]:book[collection].map(e=>e.id===id?{...e,deletedAt:new Date().toISOString()}:e)};if(await save(next)){setUndo({kind,id});setNotice("Moved to Trash. You can restore it in Data & backup.");}}
