 async function purge(){if(!window.confirm("Permanently delete everything in Trash, including photos used only by those records? Export a backup first. This cannot be undone."))return;const removed=new Set([...book.batches,...book.kombuchaBatches].filter(b=>b.deletedAt).map(b=>b.id));const next={...book,batches:book.batches.filter(b=>!b.deletedAt),entries:book.entries.filter(e=>!e.deletedAt&&!removed.has(e.batchId)),kombuchaBatches:book.kombuchaBatches.filter(b=>!b.deletedAt),kombuchaEntries:book.kombuchaEntries.filter(e=>!e.deletedAt&&!removed.has(e.batchId))};const keep=new Set(referencedPhotoIds(next));const photoIds=referencedPhotoIds(book).filter(id=>!keep.has(id));if(await save(next)){const cleanup=await cleanupPhotos(photoIds);setUndo(null);if(!cleanup.failed.length&&!cleanup.quotaFailed)setNotice("Trash emptied.");}}
 function requestExport(){if(hasDrafts)setExportConfirm(true);else void exportBook();}
 async function exportBook(){
  if(lock.current)return;lock.current=true;setBusy(true);setExporting(true);setBackup(null);setExportConfirm(false);setError("");setNotice("");
  try{
   const latest=await readNotebook();if(latest.revision!==revision)throw new Error("Newer saved records are available. Refresh, then prepare a new backup. Your drafts will stay here.");
   const snapshot=backupSnapshot(book,revision),photos:Record<string,string>={};
   for(const id of referencedPhotoIds(book))photos[id]=await blobData(await readPhoto(id));
   const blob=new Blob([JSON.stringify({format:"small-batch-fieldbook",version:2,exportedAt:snapshot.generatedAt,book,photos})],{type:"application/json"});
   setBackup({...snapshot,url:URL.createObjectURL(blob)});setNotice("Backup prepared. Download the JSON file to keep this snapshot.");
  }catch(e){setError(errText(e));}finally{lock.current=false;setBusy(false);setExporting(false);}
 }
 async function checkImportQuota(){setCheckingImport(true);setImportQuota(null);try{setImportQuota((await refreshQuota()).count);}catch(e){setError(`Photo capacity could not be checked. ${errText(e)}`);}finally{setCheckingImport(false);}}
 async function inspectImport(file:File|undefined){
  if(!file)return;setError("");setImportQuota(null);
  try{if(file.size>90000000)throw new Error("Backup exceeds the 90 MB import limit.");const raw=JSON.parse(await file.text());if(raw.format!=="small-batch-fieldbook"||![1,2].includes(raw.version))throw new Error("Choose a Fieldbook JSON backup (version 1 or 2).");const incoming=notebookSchema.parse(raw.book),ids=referencedPhotoIds(incoming);if(!raw.photos||typeof raw.photos!=="object"||ids.length>60)throw new Error("Backup photo data is invalid.");for(const id of ids)decodePhoto(raw.photos[id]);setPendingImport({book:incoming,photos:raw.photos});await checkImportQuota();}
  catch(e){setError(errText(e));}finally{if(importInput.current)importInput.current.value="";}
 }
 async function importBook(){
  if(!pendingImport||lock.current)return;lock.current=true;setBusy(true);setBackup(null);setError("");setNotice("");const created:string[]=[];
  try{
   const incoming=pendingImport.book;const stored=(await refreshQuota()).count;setImportQuota(stored);const check=importPreflight(book,incoming,stored);if(!check.allowed)throw new Error(check.errors.join(" "));
   const photoIds=new Map<string,string>();for(const id of referencedPhotoIds(incoming)){const r=await addPhoto(decodePhoto(pendingImport.photos[id]));created.push(r.id);photoIds.set(id,r.id);}
   const next=mergeNotebook(book,incoming,photoIds);
   notebookSchema.parse(next);const data=await writeNotebook(next,revision);
   setBook(next);setRevision(data.revision);setUpdated(data.updatedAt);setPersistenceIssue("");setQuota(stored+created.length);setPendingImport(null);setNotice("Backup added as separate batches. Existing records were preserved.");
  }catch(e){const message=errText(e);setPersistenceIssue("Import not saved");const cleanup=await cleanupPhotos(created);setError(message+(cleanup.failed.length||cleanup.quotaFailed?` Rollback removed ${cleanup.removed} photos; ${cleanup.failed.length} could not be removed.${cleanup.quotaFailed?" Photo count is unavailable.":""} Cancel and retry Clean unused photos in Data & backup.`:""));}finally{lock.current=false;setBusy(false);}
 }



