 function renderEntry(e:Entry){return <article className="journal-entry" key={e.id}><div className="entry-top"><span className="pill">{e.type.replace("-"," ")}</span><DateLabel value={e.at}/><span className={`pill status-${e.status}`}>{e.status==="unconfirmed"?"Review needed":e.status}</span><div className="entry-actions"><button className="icon-button" disabled={busy} aria-label={`Edit ${e.title||"entry"}`} onClick={()=>newEntry(e.type,e)}><Pencil size={17}/></button><button className="icon-button" disabled={busy} aria-label={`Delete ${e.title||"entry"}`} onClick={()=>remove("entry",e.id)}><Trash2 size={17}/></button></div></div>{e.title&&<h3>{e.title}</h3>}{e.note&&<p className="entry-note">{e.note}</p>}<div className="entry-readings">{e.phase&&<span>{guide.find(g=>g.id===e.phase)?.short}</span>}{e.tempC!==null&&<span><Thermometer size={16}/>{asTemp(e.tempC)} · {e.tempKind==="beer"?"beer / wort":"room air"}</span>}{e.gravity!==null&&<span><Droplets size={16}/>{e.gravity.toFixed(3)} SG</span>}{e.volumeL!==null&&<span>{asVolume(e.volumeL)}</span>}{e.bottling?.sugarGrams!=null&&<span>{e.bottling.sugarGrams} g {e.bottling.sugarType||"priming sugar"}</span>}{e.bottling?.bottles!=null&&<span>{e.bottling.bottles} bottles</span>}{e.bottling?.co2!=null&&<span>{e.bottling.co2} vol CO₂ target</span>}{e.bottling?.peakTempC!=null&&<span>Peak fermentation {asTemp(e.bottling.peakTempC)}</span>}</div>{e.type==="bottling"&&missingPrimingInputs({volume:e.volumeL,sugarType:e.bottling?.sugarType??"",sugarGrams:e.bottling?.sugarGrams??null,peakTemp:e.bottling?.peakTempC??null,co2:e.bottling?.co2??null}).length>0&&<p className="inline-warning small">Partial priming record · missing {missingPrimingInputs({volume:e.volumeL,sugarType:e.bottling?.sugarType??"",sugarGrams:e.bottling?.sugarGrams??null,peakTemp:e.bottling?.peakTempC??null,co2:e.bottling?.co2??null}).join(", ")}.</p>}{e.photos.length>0&&<div className="photo-grid">{e.photos.map(p=><button key={p.id} onClick={()=>setPhoto(p)} aria-label={`View photo: ${p.caption||"Batch photo"}`}><NotebookPhoto photoId={p.id} alt={p.caption||"Batch photo"} loading="lazy"/><span>{p.caption}</span></button>)}</div>}</article>}
